  5→import * as React from 'react';
  6→import { classNames as cx, type ClassNameArgument } from '../../../util/componentUtil.ts';
  7→import * as ReactTable from 'react-table';
  8→
  9→import { InputSearch } from '../../forms/controls/Input/InputSearch.tsx';
 10→import { type TableContextState, createTableContext, useTable } from './DataTableContext.tsx';
 11→import { Pagination } from './pagination/Pagination.tsx';
 12→import { MultiSearch as MultiSearchInput } from '../MultiSearch/MultiSearch.tsx';
 13→import { DataTableSync } from './table/DataTable.tsx';
 14→
 15→import cl from './DataTableEager.module.scss';
 16→
 17→export * from './DataTableContext.tsx';
 18→export { Pagination };
 19→export { DataTablePlaceholderEmpty, DataTablePlaceholderError } from './table/DataTablePlaceholder.tsx';
 20→
 21→
 22→interface ReactTableOptions<D extends object> extends ReactTable.TableOptions<D> {
 23→  // Add custom properties here
 24→  //onClick?: (row: ReactTable.Row<D>) => void,
 25→}
 26→
 27→export type TableProviderEagerProps<D extends object> = {
 28→  children: React.ReactNode,
 29→  columns: ReactTableOptions<D>['columns'],
 30→  items: ReactTableOptions<D>['data'],
 31→  getRowId: ReactTableOptions<D>['getRowId'],
 32→  isRowSelectDisabled?: ReactTable.TableInstance<D>['isRowSelectDisabled'],
 33→  plugins?: Array<ReactTable.PluginHook<D>>,
 34→  stickyColumns?: ReactTable.TableInstance<D>['bkStickyColumns'],
 35→  initialState?: Partial<ReactTable.TableState<D>>,
 36→  isReady?: boolean,
 37→};
 38→export const TableProviderEager = <D extends object>(props: TableProviderEagerProps<D>) => {
 39→  const {
 40→    children,
 41→    columns,
 42→    stickyColumns,
 43→    items,
 44→    getRowId,
 45→    isRowSelectDisabled,
 46→    plugins = [],
 47→    initialState = {},
 48→    isReady = true,
 49→  } = props;
 50→  
 51→  const tableOptions: ReactTable.TableOptions<D> = {
 52→    columns,
 53→    data: items,
 54→    ...(getRowId && { getRowId }),
 55→    ...(stickyColumns ? { bkStickyColumns: stickyColumns } : {}),
 56→    ...(isRowSelectDisabled ? { isRowSelectDisabled } : {}),
 57→  };
 58→
 59→  const table = ReactTable.useTable(
 60→    {
 61→      ...tableOptions,
 62→      defaultColumn: {
 63→        disableGlobalFilter: true,
 64→        disableSortBy: true,
 65→      },
 66→      
 67→      initialState: {
 68→        // useSortBy
 69→        sortBy: [{ id: 'name', desc: false }],
 70→        
 71→        // useGlobalFilter
 72→        globalFilter: '',
 73→        
 74→        // useFilters
 75→        filters: [],
 76→        
 77→        // usePagination
 78→        pageSize: 10,
 79→        pageIndex: 0,
 80→        
 81→        ...initialState,
 82→      },
 83→      
 84→      // useGlobalFilter
 85→      manualGlobalFilter: false,
 86→      
 87→      // useSortBy
 88→      disableSortRemove: true,
 89→      
 90→      // usePagination
 91→      manualPagination: false,
 92→      autoResetPage: false, // Do not automatically reset to first page if the data changes
 93→    },
 94→    ReactTable.useGlobalFilter,
 95→    ReactTable.useFilters,
 96→    ReactTable.useSortBy,
 97→    ReactTable.usePagination,
 98→    ReactTable.useRowSelect,
 99→    ...plugins,
100→  );
101→  
102→  // Note: the `table` reference is mutated, so cannot use it as dependency for `useMemo` directly
103→  // biome-ignore lint/correctness/useExhaustiveDependencies: (See above.)
104→  const context = React.useMemo<TableContextState<D>>(() => ({
105→    status: { ready: isReady, loading: false, error: null },
106→    setStatus() {},
107→    reload() {},
108→    table,
109→  }), [table.state, ...Object.values(tableOptions)]);
110→  
111→  const TableContext = React.useMemo(() => createTableContext<D>(), []);
112→  
113→  return (
114→    <TableContext value={context}>
115→      {children}
116→    </TableContext>
117→  );
118→};
119→TableProviderEager.displayName = 'TableProviderEager';
120→
121→
122→export const Search = (props: React.ComponentProps<typeof InputSearch>) => {
123→  const { table } = useTable();
124→  
125→  return (
126→    <InputSearch
127→      value={table.state.globalFilter ?? ''}
128→      onChange={evt => { table.setGlobalFilter(evt.target.value); }}
129→      {...props}
130→    />
131→  );
132→};
133→
134→export const MultiSearch = (props: React.ComponentPropsWithoutRef<typeof MultiSearchInput>) => {
135→  const { table } = useTable();
136→  
137→  return (
138→    <MultiSearchInput
139→      value={table.state.globalFilter ?? ''}
140→      filters={table.state.customFilters}
141→      query={filters => { table.setCustomFilters(filters); }}
142→      {...props}
143→    />
144→  );
145→};
146→MultiSearch.displayName = 'MultiSearch';
147→
148→export type DataTableEagerProps = Omit<React.ComponentProps<typeof DataTableSync>, 'table' | 'status'> & {
149→  children?: React.ReactNode,
150→  className?: ClassNameArgument,
151→  footer?: React.ReactNode,
152→};
153→export const DataTableEager = ({ children, className, footer, ...propsRest }: DataTableEagerProps) => {
154→  const { table, status } = useTable();
155→  
156→  React.useEffect(() => {
157→    if (table.page.length === 0 && table.state.pageIndex > 0 && table.canPreviousPage) {
158→      // Edge case: no items and yet we are not on the first page. Navigate back to the previous page.
159→      table.previousPage();
160→    }
161→  }, [table.page.length, table.state.pageIndex, table.canPreviousPage, table.previousPage]);
162→  
163→  // Use `<Pagination/>` by default, unless the table is empty (in which case there are "zero" pages)
164→  const footerDefault = status.ready && table.rows.length > 0 ? <Pagination/> : null;
165→  const footerWithFallback = typeof footer === 'undefined' ? footerDefault : footer;
166→  
167→  return (
168→    <DataTableSync
169→      footer={footerWithFallback}
170→      {...propsRest}
171→      className={cx(
172→        cl['bk-data-table-eager'],
173→        { [cl['bk-data-table-eager--loading']]: !status.ready },
174→        className,
175→      )}
176→      table={table}
177→      status={status}
178→    >
179→      {children}
180→    </DataTableSync>
181→  );
182→};
183→DataTableEager.displayName = 'DataTableEager';
