 5→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
 6→import * as React from 'react';
 7→
 8→import { icons } from '../../../assets/icons/_icons.ts';
 9→import cl from './Icon.module.scss';
10→
11→
12→export { cl as IconClassNames };
13→
14→export type IconName = keyof typeof icons;
15→export const iconNames = new Set(Object.keys(icons) as Array<IconName>);
16→export const isIconName = (iconName: string): iconName is IconName => {
17→  return (iconNames as Set<string>).has(iconName);
18→};
19→
20→export type Decoration = (
21→  | { type: 'background-circle' }
22→);
23→
24→type EventProps = {
25→  event: 'warning',
26→};
27→const Event = (props: EventProps) => {
28→  if (props.event !== 'warning') {
29→    return null;
30→  }
31→  const icon: IconName = props.event === 'warning' ? 'warning-filled' : props.event;
32→  return (
33→    <Icon icon={icon} className={cl[`bk-icon-event--${icon}`]} />
34→  );
35→};
