 27→// COMBO BOX INPUT
 28→// ---------------------------------------------------------------------------------------------------------------------
 29→
 30→type ComboBoxInputProps = Omit<InputProps, 'onSelect'> & {
 31→  anchorRenderArgs: AnchorRenderArgs,
 32→  onUpdate?: undefined | MenuProviderProps['onSelect'],
 33→  Input?: undefined | React.ComponentType<InputProps>,
 34→};
 35→const ComboBoxInput = (props: ComboBoxInputProps) => {
 36→  const {
 37→    anchorRenderArgs,
 38→    onUpdate,
 39→    Input = InputDefault,
 40→    // Hidden input props
 41→    name,
 42→    form,
 43→    ...propsRest
 44→  } = props;
 45→
 46→  const {
 47→    props: anchorRenderProps,
 48→    open,
 49→    selectedOption,
 50→  } = anchorRenderArgs;
 51→  
 52→  const anchorProps = anchorRenderProps({
 53→    className: cx(
 54→      cl['bk-combo-box'],
 55→      { [cl['bk-combo-box--open']]: open },
 56→      propsRest.containerProps?.className,
 57→    ),
 58→  });
 59→
 60→  return (
 61→    <>
 62→      <Input
 63→        role="combobox"
 64→        automaticResize
 65→        {...propsRest}
 66→        inputProps={{
 67→          placeholder: 'Select options',
 68→          ...propsRest.inputProps,
 69→          className: cx(cl['bk-combo-box__input'], propsRest.inputProps?.className),
 70→        }}
 71→        containerProps={{
 72→          ...propsRest.containerProps,
 73→          ...anchorProps,
 74→        }}
 75→      />
 76→
 77→      {/* Render a hidden input with the selected option key (rather than the human-readable label). */}
 78→      {typeof name === 'string' &&
 79→        <input
 80→          type="hidden"
 81→          form={form}
 82→          name={name}
 83→          value={selectedOption?.itemKey ?? ''}
 84→        />
 85→      }
 86→    </>
 87→  );
 88→};
 89→
 90→// COMBO BOX
 91→// ---------------------------------------------------------------------------------------------------------------------
 92→
 93→/**
 94→ * A `ComboBox` is a text input control combined with a dropdown menu that adapts
 95→ * to the user input, for example for automatic suggestions.
 96→ * 
 97→ * References: 
 98→ * - [1] https://www.w3.org/WAI/ARIA/apg/patterns/combobox
 99→ */
100→export type ComboBoxProps = Omit<InputProps, 'onSelect'> & {
101→  /** Whether this component should be unstyled. */
102→  unstyled?: undefined | boolean,
103→  
104→  /** A human-readable name for the combobox. */
105→  label: string,
106→  
107→  /** A custom `Input` component. */
108→  Input?: undefined | React.ComponentType<InputProps>,
109→  
110→  /** The options list to be shown in the dropdown menu. */
111→  options: React.ReactNode,
112→  
113→  /** The option to select. If `undefined`, this component will be considered uncontrolled. */
114→  selected?: undefined | null | ItemKey,
115→  
116→  /** Callback for when an option is selected in the dropdown menu. */
117→  onSelect?: undefined | React.ComponentProps<typeof MenuProvider>['onSelect'],
118→
119→  /** Additional props to be passed to the `MenuProvider`. */
120→  dropdownProps?: undefined | Partial<MenuProviderProps>,
121→};
122→export const ComboBox = Object.assign(
123→  (props: ComboBoxProps) => {
124→    const {
125→      unstyled = false,
126→      label,
127→      Input = InputDefault,
128→      options,
129→      selected,
130→      onSelect,
131→      dropdownProps = {},
132→      ...propsRest
133→    } = props;
134→    
135→    const [inputValue, setInputValue] = React.useState(() => {
136→      return selected
137→        ? dropdownProps.formatItemLabel?.(selected) ?? ''
138→        : propsRest.value ?? '';
139→    });
140→
141→    React.useEffect(
142→      () => {
143→        if (typeof propsRest.value === 'undefined' && selected) {
144→          // Update Input value state on selection change when menu
145→          // selection is controlled input value is uncontrolled
146→          setInputValue(dropdownProps.formatItemLabel?.(selected) ?? '');
147→        }
148→      },
149→      [propsRest.value, selected, dropdownProps.formatItemLabel],
150→    );
151→
152→    const selectedSet = React.useMemo(() => selectionStateFromItemKey(selected), [selected]);
153→    const {
154→      internalSelected,
155→      handleInternalSelect,
156→    } = useComboBoxState({
157→      selected: selectedSet,
158→      formatItemLabel: dropdownProps.formatItemLabel,
159→    });
160→
161→    const internalSelectedItemKey: null | ItemKey = internalSelected.keys().next().value ?? null;
162→
163→    const handleSelect = React.useCallback((_key: null | ItemKey, itemDetails: null | ItemDetails) => {
164→      const itemKey = itemDetails?.itemKey ?? null;
165→      onSelect?.(itemKey, itemDetails);
166→      setInputValue(itemDetails?.label ?? '');
167→      handleInternalSelect(itemKey ? new Set([itemKey]) : new Set());
168→    }, [onSelect, handleInternalSelect]);
169→
170→    const handleInputChange = (evt: React.ChangeEvent<HTMLInputElement>) => {
171→      const value = evt.target.value;
172→      setInputValue(value);
173→    };
174→
175→    const handleInputFocusOut = (evt: React.FocusEvent<HTMLInputElement>) => {
176→      const value = evt.target.value;
177→
178→      if (value === '') {
179→        handleSelect(null, null);
180→      } else {
181→        setInputValue(internalSelected.values().next().value?.label ?? '');
182→      }
183→    };
184→
185→    return (
186→      <MenuProvider
187→        label={label}
188→        items={options}
189→        role="combobox"
190→        triggerAction="focus-interactive" // Keep the dropdown menu open while the input is focused
191→        keyboardInteractions="form-control" // FIXME
192→        placement="bottom-start"
193→        offset={1}
194→        selected={internalSelectedItemKey}
195→        onSelect={handleSelect}
196→        {...dropdownProps}
197→      >
198→        {anchorRenderArgs => (
199→          <ComboBoxInput
200→            anchorRenderArgs={anchorRenderArgs}
201→            Input={Input}
202→            value={inputValue}
203→            onChange={handleInputChange}
204→            onBlur={handleInputFocusOut}
205→            {...propsRest}
206→          />
207→        )} 
208→      </MenuProvider>
209→    );
210→  },
211→  {
212→    Static: MenuProvider.Static,
213→    Option: MenuProvider.Option,
214→    Header: MenuProvider.Header,
215→    Action: MenuProvider.Action,
216→    FooterActions: MenuProvider.FooterActions,
217→  },
218→);
