 69→export const ToastCopyAction = ({ toast }: { toast: ToastDescriptor }) => {
 70→  const defaultLabel = 'Copy';
 71→  const [label, setLabel] = React.useState(defaultLabel);
 72→  
 73→  const handleCopy = React.useCallback(async (message: string) => {
 74→    try {
 75→      // Idea: use `write()` with HTML mime type to copy arbitrary content? Could get the `innerHTML` through a ref.
 76→      if (navigator.clipboard.writeText) {
 77→        await navigator.clipboard.writeText(message);
 78→      }
 79→      
 80→      setLabel('Copied!');
 81→    } catch (error: unknown) {
 82→      setLabel('Error: unable to copy');
 83→    }
 84→  }, []);
 85→  
 86→  const message = toast.message;
 87→  
 88→  // Currently don't support copying unless the message is a string
 89→  if (typeof message !== 'string') { return null; }
 90→  
 91→  return (
 92→    <Banner.ActionIcon
 93→      icon="copy"
 94→      label={label}
 95→      onPress={() => handleCopy(message)} // Note: careful to return the promise here to `onPress`
 96→      onMouseLeave={() => {
 97→        // Reset the label after exit animation had a chance to complete
 98→        window.setTimeout(() => { setLabel(defaultLabel); }, 500);
 99→      }}
100→    />

